/* The same voiceover/footage/caption workflows are available in the app and MCP. */
let workflowAudioId=null,workflowBusy=false;
function stageWorkflow(operations){const next=Model.clone(project),created=[];const editable=c=>{if(!c)throw new Error('A clip is missing.');if(next.locked[c.track])throw new Error('Unlock the '+trackNames[c.track]+' track first.');};for(const op of operations){if(op.type==='delete'){const ids=new Set(op.clipIds);next.clips.filter(c=>ids.has(c.id)).forEach(editable);next.clips=next.clips.filter(c=>!ids.has(c.id));}else if(op.type==='update'){for(const id of op.clipIds){const c=next.clips.find(c=>c.id===id);editable(c);Object.assign(c,op.patch);}}else if(op.type==='add'){if(next.locked[op.track])throw new Error('Unlock the '+trackNames[op.track]+' track first.');const a=assets.get(op.assetId);if(!a)throw new Error('Import the selected media first.');const c={...defaultClip(a,op.start),track:op.track,in:op.in||0,duration:op.duration,...op.patch};next.clips.push(c);created.push(c.id);}}validateProject(next,[...assets.values()]);return {next,created};}
function commitWorkflow(staged){stop();checkpoint();project=staged.next;setSelection(staged.created||[]);commit();drawFrame();}
function voiceoverTarget(){return Math.max(0,...project.clips.filter(c=>c.track==='audio'&&c.audioRole!=='music').map(c=>c.start+c.duration));}
async function replaceWithVoiceover(){if(exporting||captionBusy||workflowBusy)return;const a=assets.get($('#workflow-voice').value);if(!a)return toast('Import and choose a voiceover first.');const keepMusic=$('#workflow-keep-music').checked,removeSilence=$('#workflow-clean').checked,clearCaptions=$('#workflow-clear-captions').checked,signature=snapshot();workflowAudioId=a.id;workflowBusy=true;renderLibrary();try{const operations=CutlineWorkflows.voiceover(project,a,{keepMusic});if(clearCaptions){const ids=project.clips.filter(c=>c.track==='text'&&c.isCaption).map(c=>c.id);if(ids.length)operations.push({type:'delete',clipIds:ids});}let plan;if(removeSilence){const buffer=await decodeAudioAsset(a);plan=CutlineAudioEditing.analyze(buffer,{in:0,speed:1,duration:a.duration},{thresholdDb:-38,minimum:.24,padding:.06});if(plan.allSilent||plan.retained.some(p=>p.duration<.05))throw new Error('Silence settings would remove the voice or leave tiny fragments. Use the detailed Remove silence panel instead.');}if(snapshot()!==signature||assets.get(a.id)!==a||exporting)throw new Error('The project changed. Apply the voiceover again.');const staged=stageWorkflow(operations);if(plan?.gaps.length){const c=staged.next.clips.find(c=>c.id===staged.created[0]),pieces=CutlineAudioEditing.segments(c,plan,Model.sliceClip,uid);staged.next.clips.splice(staged.next.clips.indexOf(c),1,...pieces);staged.created=pieces.map(c=>c.id);}commitWorkflow(staged);playhead=0;toast('Original sound replaced'+(plan?.removed?' · '+plan.removed.toFixed(2)+'s silence removed':'')+'. Extend footage and generate captions below.');}catch(error){toast(error.message);}finally{workflowBusy=false;renderLibrary();}}
function extendToVoiceover(){if(exporting||captionBusy||workflowBusy)return;try{const assetIds=$$('[data-workflow-footage]:checked').map(el=>el.value),ops=CutlineWorkflows.fitFootage(project,[...assets.values()],{assetIds,target:voiceoverTarget(),shotLength:Number($('#workflow-shot-length').value),reuse:$('#workflow-reuse').checked});if(!ops.length)return toast('The video already reaches the narration end.');commitWorkflow(stageWorkflow(ops));toast(ops.length+' silent shots added to reach the voiceover. Original framing is unchanged.');}catch(error){toast(error.message);}}
function formatReadableCaptions(){if(exporting||captionBusy)return;if(project.locked.text)return toast('Unlock Text & captions first.');const selectedCaptions=selectionClips().filter(c=>c.track==='text'&&c.isCaption),list=selectedCaptions.length?selectedCaptions:project.clips.filter(c=>c.track==='text'&&c.isCaption);if(!list.length)return toast('Generate or import captions first.');try{const measure=document.createElement('canvas').getContext('2d'),parts=new Map();for(const c of list)parts.set(c.id,CutlineWorkflows.captions([c],{maxChars:28,maxWidth:canvas.width*.83,measure:(text,clip)=>{measure.font=`${clip.fontWeight||600} ${clip.fontSize*canvas.height/1080}px Arial, sans-serif`;return measure.measureText(text).width;}},uid));const next=Model.clone(project);next.clips=next.clips.flatMap(c=>parts.get(c.id)||[c]);validateProject(next,[...assets.values()]);commitWorkflow({next,created:[...parts.values()].flat().map(c=>c.id)});toast('Captions split into short, balanced lines. Timing and words preserved.');}catch(error){toast(error.message);}}
function addTextBlurPreset(position){if(exporting||captionBusy)return;if(project.locked.blur)return toast('Unlock Blur regions first.');const end=duration();if(end<.05)return toast('Add footage first.');checkpoint();const c={...Model.clone(defaults),id:uid(),track:'blur',name:position==='top'?'Blur top text':'Blur bottom text',start:0,duration:end,...CutlineWorkflows.blurPreset(position),opacity:100,blurRadius:32,blurMode:'blur'};project.clips.push(c);setSelection([c.id]);playhead=Math.min(playhead,end-.001);commit();drawFrame();toast('Drag the blur box to move it. Pull a side or corner to resize.');}
const libraryBeforeWorkflows=renderLibrary;
renderLibrary=function(){libraryBeforeWorkflows();const root=$('#library-content');if(tab==='captions'){root.insertAdjacentHTML('afterbegin','<button id="workflow-format-captions" class="secondary wide">Short, balanced captions</button>');$('#workflow-format-captions').onclick=formatReadableCaptions;$('#workflow-format-captions').disabled=exporting||captionBusy||project.locked.text;}
 if(!['ads','audio'].includes(tab))return;const audio=[...assets.values()].filter(a=>a.type==='audio'),videos=[...assets.values()].filter(a=>a.type==='video');const chosen=audio.some(a=>a.id===workflowAudioId)?workflowAudioId:audio[0]?.id;
 root.insertAdjacentHTML('afterbegin',`<section class="workflow-panel"><h3>Voiceover edit</h3><p class="small-help">Replace the soundtrack, clean pauses, extend footage and caption the new voice. Each action has Undo.</p><button id="workflow-import-voice" class="secondary wide">Import voiceover</button><input id="workflow-audio-file" type="file" accept="audio/*,.wav,.mp3,.m4a" hidden><label class="field">Voiceover<select id="workflow-voice">${audio.map(a=>`<option value="${a.id}" ${a.id===chosen?'selected':''}>${esc(a.name)}</option>`).join('')||'<option value="">Import audio first</option>'}</select></label><label class="workflow-check"><input type="checkbox" id="workflow-clean" checked> Remove silent gaps</label><label class="workflow-check"><input type="checkbox" id="workflow-keep-music" checked> Keep music-role tracks</label><label class="workflow-check"><input type="checkbox" id="workflow-clear-captions" checked> Clear old captions</label><button id="workflow-replace" class="primary wide">${workflowBusy?'Preparing voiceover…':'Replace original sound'}</button><details class="workflow-extension"><summary>Extend footage to narration</summary><p class="small-help">Choose extra footage. Unused parts are used first. Added shots stay silent and fit inside the frame.</p>${videos.map(a=>`<label class="workflow-check"><input type="checkbox" data-workflow-footage value="${a.id}" checked> ${esc(a.name)}</label>`).join('')||'<p class="small-help">Import more video in Media.</p>'}<label class="field">Shot length · seconds<input id="workflow-shot-length" type="number" min=".1" max="60" value="4" step=".1"></label><label class="workflow-check"><input type="checkbox" id="workflow-reuse"> Allow footage reuse if needed</label><button id="workflow-extend" class="secondary wide">Extend to voiceover</button></details><button id="workflow-captions" class="secondary wide">Open auto captions for new voice</button></section><section class="workflow-panel"><h3>Hide existing text</h3><p class="small-help">Blur English text without cropping. Drag the box or resize it with the edge and corner handles.</p><div class="pill-row"><button id="workflow-blur-top" class="secondary">Blur top text</button><button id="workflow-blur-bottom" class="secondary">Blur bottom text</button></div></section>`);
 $('#workflow-import-voice').onclick=()=>$('#workflow-audio-file').click();$('#workflow-audio-file').onchange=async e=>{const imported=await importFiles([...e.target.files]);if(imported[0])workflowAudioId=imported[0].id;tab='ads';renderLibrary();};$('#workflow-voice').onchange=e=>workflowAudioId=e.target.value;$('#workflow-replace').onclick=replaceWithVoiceover;$('#workflow-extend').onclick=extendToVoiceover;$('#workflow-blur-top').onclick=()=>addTextBlurPreset('top');$('#workflow-blur-bottom').onclick=()=>addTextBlurPreset('bottom');$('#workflow-captions').onclick=()=>{tab='captions';renderLibrary();$('#caption-source').value='mix';$('#caption-language').value='fr';};if(exporting||captionBusy||workflowBusy)$$('.workflow-panel button,.workflow-panel input,.workflow-panel select',root).forEach(el=>el.disabled=true);
};
